import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BGlkWkwp.js";const m=JSON.parse('{"title":"Note","description":"","frontmatter":{},"headers":[],"relativePath":"components/note.md","filePath":"components/note.md"}'),n={name:"components/note.md"};function i(d,e,s,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="note" tabindex="-1">Note <a class="header-anchor" href="#note" aria-label="Permalink to &quot;Note&quot;">​</a></h1><p>Note is a remark without a line or a surface.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for one sentence that adds to what is around it. A notice with a line is a <a href="./banner">Banner</a>; the remark under an input is the note of its <a href="./field">Field</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>tone</code></td><td></td><td><code>warn</code> (yellow) or <code>error</code> (red); muted without it</td></tr><tr><td><code>icon</code></td><td></td><td>An icon before the text (a name or a component)</td></tr><tr><td><code>clamp</code></td><td><code>false</code></td><td>One line with an ellipsis</td></tr><tr><td><code>children</code></td><td>required</td><td>The text</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>It is text in the caption role, muted or in the color of its tone. An icon is gap-sm from the text and centred on the ink of the first line. In a layout the text keeps its line box; inside a control, such as a list item, it is trimmed to its ink. With <code>clamp</code> it is one line with an ellipsis, and the full text shows on hover and on keyboard focus.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/note/" title="Note" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/note/" target="_blank" rel="noopener">Note</a></figcaption></figure>',10)])])}const u=t(n,[["render",i]]);export{m as __pageData,u as default};
